// Isolated browser fixture. Production mining authority is exercised by PostgreSQL tests.
export function miningWorld(state,waterfront,playerId){
 const names=['Mines and Quarries','Old Town','Downtown','The Waterfront','Industrial Quarter','Blackwater Island','Drilling Shore'];
 const slugs=['mines-and-quarries','old-town','downtown','the-waterfront','industrial-quarter','blackwater-island','drilling-shore'];
 const catalog=slugs.map((slug,i)=>slug==='the-waterfront'?waterfront.district:{...waterfront.district,id:'district-'+i,slug,name:names[i],district_type:i===0?'mining':'urban',description:i===0?'Deep in the hills and stone, opportunity runs rich. Own the land. Control the supply.':'A district of Blackwater.',tagline:i===0?'Raw materials build Blackwater.':'Build your place in the city.',image_url:i===0?'/art/mining/map.webp':'/art/command-city.jpg',available_plots:0,active_businesses:0,industries:i===0?['Mining','Quarrying','Freight']:[],map_data:{}});
 const d=catalog[0];let admin=true,shift=null,durability=0,history=[],nonce=new Map();
 const rows=[['North Ridge Iron Mine','iron-ore','open','public',200,125],['Crown Stone Quarry','stone','open','public',515,150],['Copperhead Mine','copper-ore','closed','private',970,140],['East Quarry','limestone','open','private',1040,300],['Blackrock Coal Mine','coal','open','public',615,290],['Westbank Limestone','limestone','closed','private',170,285],['Southern Claim','iron-ore','reserved','private',365,398],['Deep Rock Claim','stone','reserved','private',660,476],['High Ridge Claim','copper-ore','closed','private',960,442],['Riverbed Quarry','stone','open','public',800,555]];
 const raw=[['iron-ore','Iron ore'],['stone','Stone'],['copper-ore','Copper ore'],['coal','Coal'],['limestone','Limestone']];
 const sites=rows.map(([name,good_id,status,access_mode,map_x,map_y],i)=>({id:'mine-'+i,definition_id:'mine-def-'+i,plot_id:'mine-plot-'+i,district_id:d.id,code:'MQ-'+String(i+1).padStart(2,'0'),name,description:'A registered Blackwater extraction site. Resources drive industry, trade and influence.',good_id,good_name:raw.find(g=>g[0]===good_id)[1],image_url:'/art/mining/'+(['stone','limestone'].includes(good_id)?'quarry':'mine')+'.webp',status,access_mode,map_x,map_y,remaining:2000000,initial_reserve:2000000,hand_yield:4,hand_seconds:60,tool_wear:1,operation_yield:40,operation_seconds:300,operated_at:new Date().toISOString(),transport:'Rail + road',survey_status:'Surveyed',owner_type:'city',owner_id:'mining-authority',owner_name:'Blackwater Mining Authority',base_price:125000,tax_rate:3,active_shifts:0,ready_output:0,output_today:0,auction:null}));
 const events=sites.map((s,i)=>({id:100+i,district_id:d.id,category:'resources',event_type:'mine_registered',description:s.name+' registered in the extraction registry.',actor_id:null,actor_name:'City',plot_id:s.plot_id,business_id:null,gang_id:null,created_at:new Date().toISOString()}));
 function district(slug){const found=catalog.find(d=>d.slug===slug||d.id===slug)||waterfront.district;if(found.slug==='the-waterfront')return {...waterfront,districts:catalog,cash:state.player.cash};return {...waterfront,district:found,districts:catalog,plots:[],buildings:[],businesses:[],sites:[],events:found.id===d.id?events:[],territory:{controller_name:'Neutral',neutral_influence:100,fortification:0,status:'neutral'},influence:[],market:[],trades:[],buy_orders:[],cash:state.player.cash};}
 function activate(){for(const [id,name]of raw)if(!state.goods.some(g=>g.id===id))state.goods.push({id,name,business_available:false,business_name:name,business_cost:1,batch_size:1,cycle_seconds:60});}
 function read(){activate();return {world:district(d.slug),sites,can_manage:admin,server_time:new Date().toISOString(),playable:state.season.status==='open',season_end:null,tool:{durability},shift,inventory:raw.map(([good_id,name])=>({good_id,name,quantity:state.inventory.find(g=>g.good_id===good_id)?.quantity||0})),history,settings:{mining_pickaxe_durability:100,mining_respect_per_shift:2,mining_offline_cycles:24,mining_auction_default_minutes:1440,mining_auction_min_minutes:5,mining_auction_max_minutes:10080,district_bid_increment:100}};}
 function action(action,p){activate();const key=action+':'+p.request_id;if(nonce.has(key))return nonce.get(key);const site=sites.find(s=>s.id===p.mine_id);let result={message:'Mine updated.'};
 if(action==='pickaxe')return {error:'Pickaxes cannot be purchased. Finding equipment will be available in a future update.'};
 if(action==='start'){if(!site||site.status!=='open'||site.access_mode!=='public'||shift||durability<1)return {error:'This site is unavailable.'};durability--;site.remaining-=4;site.active_shifts++;shift={id:'shift-'+Date.now(),mine_id:site.id,mine_name:site.name,code:site.code,good_id:site.good_id,good_name:site.good_name,quantity:4,respect:2,wear:1,started_at:new Date().toISOString(),ready_at:new Date(Date.now()+60000).toISOString()};result={message:'Mining shift started.',run_id:shift.id};}
 if(action==='claim'){if(!shift||Date.parse(shift.ready_at)>Date.now())return {error:'Shift is not ready.'};let item=state.inventory.find(g=>g.good_id===shift.good_id);if(!item){item={good_id:shift.good_id,quantity:0};state.inventory.push(item);}item.quantity+=4;state.player.xp+=2;site.active_shifts--;site.output_today+=4;history.unshift({...shift,id:Date.now(),source:'shift',created_at:new Date().toISOString()});shift=null;result.message='Resources added to your inventory.';}
 if(action==='cancel'){if(!shift)return {error:'No active shift.'};site.remaining+=4;site.active_shifts--;shift=null;result.message='Shift cancelled.';}
 if(action==='manage'){if(!admin)return {error:'Owner permission required.'};Object.assign(site,p);result.message='Mine settings saved. The change is audited.';}
 if(action==='auction'){site.auction={id:'auction-'+Date.now(),plot_id:site.plot_id,seller_id:null,city_sale:true,minimum_bid:p.price,bid:0,bidder_id:null,bidder_name:null,escrow:0,tax_rate:3,ends_at:new Date(Date.now()+p.minutes*60000).toISOString(),status:'open'};result.message='Mine auction opened.';}
 if(action==='bid'){const a=site.auction;if(!a||p.price<a.minimum_bid)return {error:'Bid too low.'};state.player.cash-=p.price+Math.ceil(p.price*.03)-a.escrow;Object.assign(a,{bid:p.price,bidder_id:playerId,bidder_name:state.player.handle,escrow:p.price+Math.ceil(p.price*.03)});result.message='Mine bid reserved.';}
 if(action==='cancel_auction'){site.auction=null;result.message='Auction cancelled.';}
 nonce.set(key,result);return result;}
 return {district,read,action,activate,setDurability:value=>{durability=value;},equip:()=>{durability=100;},finish:()=>{if(shift)shift.ready_at=new Date(Date.now()-1000).toISOString();},player:()=>{admin=false;},catalog};
}
